__NUXT_JSONP__("/ar/how-to-apply/student-visa-f1/transfer-students", {data:[{details:{slug:"ar",pageTitle:"الطلاب الراغبون في التحويل | Mentor Language Institute",pageDescription:"الطلاب الذين يدرسون حاليًا في مؤسسة تعليمية أخرى في الولايات المتحدة ويريدون تغيير المدارس .",title:"الطلاب الراغبون في التحويل",image:"\u002Fimages\u002Fhow-to-apply\u002Ftransfer-students\u002Ftransfer-students.jpg",section:[{description:["الطلاب الذين يدرسون حاليًا في مؤسسة تعليمية أخرى في الولايات المتحدة \u003Cbr\u002F\u003Eويريدون تغيير المدارس ."]}],category:[{title:"خطوات الأبلكيشن",image:"\u002Fimages\u002Fhow-to-apply\u002Ftransfer-students\u002Fapplication-steps-ar.png",listType:"decimal",lists:["تقدم إلى منتور (تقدم بملىء الإستمارة أونلاين)","ارفع المستندات المطلوبة","حضور اللقاء التعريفي للطلاب الجدد","احصل على آي20 جديد"],description:["على الطلاب التقدم إلى منتور بمدة شهر أو شهرين قبل بداية البرانامج. يقترح التواصل والتحدث مع المستشار الطلابي في مينتور بعد التقدم أونلاين للتحقق من إكتمال خطوات التحويل إلى معهدنا وذلك لتجنت أي تعارض قد يعرقل عملية التحويل بناء على حالة الطالب."],hasApplyNow:true},{title:"سياسة الإلغاء",description:["يتوجب على الطالب دفع رسوم التسجيل منذ البداية عند تقديم الأبلكيشن . رسوم التسجيل هي رسوم تدفع مرة واحدة وهي غير مستردة بغض النظر سواء تم قبول أو رفض المتقدم"]},{title:"بعد تقديم الأبلكيشن",image:"\u002Fimages\u002Fhow-to-apply\u002Ftransfer-students\u002Fapplication-form-en.jpg",description:["بعد أن يتقدم الطالب برفع الأبلكيشن أونلاين, سوف نقوم في مينتور ببدأ إجراءات القبول و سوف نرسل له رابط مينتور iMLI (لكل طالب رابط ابلكيشن أونلاين). يستطيع الطالب متابعة خطوات الأبلكيشن وحالته عن طريق iMLI."]}],applyOnline:{title:"تقدم أونلاين",description:["املىء الإستمارة أونلاين"],imageLink:{image:"\u002Fimages\u002Fhow-to-apply\u002Ftransfer-students\u002Fapply-now-ar.png",link:"\u002Far\u002Fadmission"}},dir:"\u002Ftransfer-students",path:"\u002Ftransfer-students\u002Far",extension:".json",createdAt:"2026-10-22T16:31:31.272Z",updatedAt:"2025-05-26T12:06:27.944Z"}}],fetch:{},mutations:void 0});